globalThis.GROUND_PROGRAMS = {"turboslide":{"body":"// Turboslide ground: the product's paper:dithering sphere, printed through the shader's 8x8 Bayer table at\n// 2 css px cells, ported from Turboslide@3e22c8f54 apps/studio/src/components/site/pattern-cells.ts (printPattern).\n// Uniforms and defaults: u_ink #F2F2F0 on u_paper #070707 (dark) or #070707 on #FFFFFF (light); u_cell 2.0;\n// u_k 0.0 (auto: 0.82 / rows, the sphere ~75% of the height); u_offset (0.0, 0.0) centred, the page recipe is (0.28, 0.04);\n// u_period 0.0 keeps the page's light, cos(0.75 t) and sin(0.625 t); u_period 4.0 closes it once per 4 s (loop.mp4).\n\nuniform vec2 u_resolution;\nuniform float u_time;\nuniform float u_dpr;\nuniform vec3 u_ink;\nuniform vec3 u_paper;\nuniform float u_cell;\nuniform float u_k;\nuniform vec2 u_offset;\nuniform float u_period;\n\nconst int B[64] = int[64](0, 32, 8, 40, 2, 34, 10, 42, 48, 16, 56, 24, 50, 18, 58, 26, 12, 44, 4, 36, 14, 46, 6, 38, 60, 28,\n  52, 20, 62, 30, 54, 22, 3, 35, 11, 43, 1, 33, 9, 41, 51, 19, 59, 27, 49, 17, 57, 25, 15, 47, 7,\n  39, 13, 45, 5, 37, 63, 31, 55, 23, 61, 29, 53, 21);\nvoid groundMain() {\n  float cell = max(1.0, u_cell * u_dpr);\n  vec2 grid = floor(u_resolution / cell);\n  vec2 c = floor(FC.xy / cell);\n  float iy = c.y - floor(grid.y * 0.5);\n  float ix = c.x - floor(grid.x * 0.5);\n  float k = u_k > 0.0 ? u_k : 0.82 / grid.y;\n  float sc = 2.0 / 0.62;\n  float x = ((ix + 0.5) * k + u_offset.x) * sc;\n  float y = ((iy + 0.5) * k + u_offset.y) * sc;\n  float d = 1.0 - x * x - y * y;\n  vec3 L;\n  if (u_period > 0.0) { float a = 6.28318530718 * u_time / u_period; L = normalize(vec3(cos(a), 0.8, sin(a))); }\n  else { float t = 0.5 * u_time; L = normalize(vec3(cos(1.5 * t), 0.8, sin(1.25 * t))); }\n  bool lit = false;\n  if (d >= 0.0) {\n    float shape = 0.5 + 0.5 * dot(L, vec3(x, y, sqrt(d)));\n    int r = int(mod(iy, 8.0));\n    int cc = int(mod(ix, 8.0));\n    lit = shape + float(B[r * 8 + cc]) / 64.0 >= 1.0;\n  }\n  outColor = vec4(lit ? u_ink : u_paper, 1.0);\n}\n","textures":{"gx_win":"data:image/png;base64,","gx_tone":"data:image/webp;base64,"}},"glyphfield":{"body":"uniform vec2 u_resolution;\nuniform vec2 u_pointer;\nuniform float u_time;\nuniform vec3 u_color_a;\nuniform vec3 u_color_b;\nuniform vec3 u_color_c;\nuniform vec3 u_lab_a;\nuniform vec3 u_lab_b;\nuniform vec3 u_lab_c;\nuniform float u_strength;\nuniform float u_detail;\nuniform float u_frequency;\nuniform float u_grain;\nuniform float u_amplitude;\nuniform float u_density;\nuniform float u_brightness;\nuniform float u_rotation;\nuniform float u_scale;\n\n\n\nconst float PI = 3.14159265359;\nconst float TAU = 6.28318530718;\n// Patterns are sized in a 900px-tall reference frame so previews and large exports match.\nuniform float REFERENCE_HEIGHT; uniform float uSeat;\nconst mat2 OCTAVE = mat2(1.6, 1.2, -1.2, 1.6);\n\n\nfloat seamlessAngularWave(float angle, float frequency, float phase, float minimumCycles) {\n  float cycles = max(minimumCycles, floor(abs(frequency) + 0.5));\n  return sin(angle * cycles + phase);\n}\n\nfloat seamlessAngularWarp(float angle, float phase) {\n  return sin(angle + phase) * 0.34 + sin(angle * 2.0 - phase * 0.625) * 0.08;\n}\n\n\n// Hash without sine (Dave Hoskins, MIT): stable across GPUs, unlike fract(sin()).\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nvec2 hash22(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.103, 0.0973));\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.xx + p3.yz) * p3.zy);\n}\n\nvec3 hash33(vec3 p3) {\n  p3 = fract(p3 * vec3(0.1031, 0.103, 0.0973));\n  p3 += dot(p3, p3.yxz + 33.33);\n  return fract((p3.xxy + p3.yxx) * p3.zyx);\n}\n\n// Quintic gradient noise, roughly -1..1.\nfloat gnoise(vec2 p) {\n  vec2 i = floor(p);\n  vec2 f = fract(p);\n  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);\n  float a = dot(hash22(i) * 2.0 - 1.0, f);\n  float b = dot(hash22(i + vec2(1.0, 0.0)) * 2.0 - 1.0, f - vec2(1.0, 0.0));\n  float c = dot(hash22(i + vec2(0.0, 1.0)) * 2.0 - 1.0, f - vec2(0.0, 1.0));\n  float d = dot(hash22(i + vec2(1.0)) * 2.0 - 1.0, f - vec2(1.0));\n  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) * 1.6;\n}\n\nfloat gnoise(vec3 p) {\n  vec3 i = floor(p);\n  vec3 f = fract(p);\n  vec3 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);\n  float n000 = dot(hash33(i) * 2.0 - 1.0, f);\n  float n100 = dot(hash33(i + vec3(1.0, 0.0, 0.0)) * 2.0 - 1.0, f - vec3(1.0, 0.0, 0.0));\n  float n010 = dot(hash33(i + vec3(0.0, 1.0, 0.0)) * 2.0 - 1.0, f - vec3(0.0, 1.0, 0.0));\n  float n110 = dot(hash33(i + vec3(1.0, 1.0, 0.0)) * 2.0 - 1.0, f - vec3(1.0, 1.0, 0.0));\n  float n001 = dot(hash33(i + vec3(0.0, 0.0, 1.0)) * 2.0 - 1.0, f - vec3(0.0, 0.0, 1.0));\n  float n101 = dot(hash33(i + vec3(1.0, 0.0, 1.0)) * 2.0 - 1.0, f - vec3(1.0, 0.0, 1.0));\n  float n011 = dot(hash33(i + vec3(0.0, 1.0, 1.0)) * 2.0 - 1.0, f - vec3(0.0, 1.0, 1.0));\n  float n111 = dot(hash33(i + vec3(1.0)) * 2.0 - 1.0, f - vec3(1.0));\n  return mix(\n    mix(mix(n000, n100, u.x), mix(n010, n110, u.x), u.y),\n    mix(mix(n001, n101, u.x), mix(n011, n111, u.x), u.y),\n    u.z\n  ) * 1.5;\n}\n\nfloat fbm(vec2 p, int octaves) {\n  float value = 0.0;\n  float amplitude = 0.5;\n  for (int index = 0; index < 6; index++) {\n    if (index >= octaves) break;\n    value += amplitude * gnoise(p);\n    p = OCTAVE * p + 11.7;\n    amplitude *= 0.5;\n  }\n  return value;\n}\n\n// Time is a third noise axis, so fields evolve instead of sliding.\nfloat fbm(vec3 p, int octaves) {\n  float value = 0.0;\n  float amplitude = 0.5;\n  for (int index = 0; index < 6; index++) {\n    if (index >= octaves) break;\n    value += amplitude * gnoise(p);\n    p = vec3(OCTAVE * p.xy, p.z * 1.7) + 7.3;\n    amplitude *= 0.5;\n  }\n  return value;\n}\n\nvec2 warp(vec2 p, float time, float amount, int octaves) {\n  return p + vec2(fbm(vec3(p, time), octaves), fbm(vec3(p + vec2(5.2, 1.3), time), octaves)) * amount;\n}\n\nvec2 studioUvAt(vec2 fragCoord) {\n  vec2 p = fragCoord / u_resolution.xy * 2.0 - 1.0;\n  p.x *= u_resolution.x / u_resolution.y;\n  p /= max(0.1, u_scale);\n  float angle = radians(u_rotation);\n  return mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * p;\n}\n\nvec2 studioUv() {\n  return studioUvAt(FC.xy);\n}\n\nvec2 referenceCoord() {\n  return FC.xy * (REFERENCE_HEIGHT / u_resolution.y);\n}\n\nvec2 referenceToFrag(vec2 reference) {\n  return reference * (u_resolution.y / REFERENCE_HEIGHT);\n}\n\nvec3 oklabToLinear(vec3 lab) {\n  float l = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;\n  float m = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;\n  float s = lab.x - 0.0894841775 * lab.y - 1.291485548 * lab.z;\n  l = l * l * l;\n  m = m * m * m;\n  s = s * s * s;\n  return max(vec3(0.0), vec3(\n    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,\n    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,\n    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s\n  ));\n}\n\nvec3 paletteLab(float t) {\n  t = clamp(t, 0.0, 1.0);\n  return t < 0.5 ? mix(u_lab_a, u_lab_b, t * 2.0) : mix(u_lab_b, u_lab_c, t * 2.0 - 1.0);\n}\n\n// Perceptual three-stop ramp: no muddy midpoints between palette colors.\nvec3 ramp(float t) {\n  return oklabToLinear(paletteLab(t));\n}\n\nvec3 mixLab(vec3 from, vec3 to, float t) {\n  return oklabToLinear(mix(from, to, t));\n}\n\nfloat luma(vec3 color) {\n  return dot(color, vec3(0.2126, 0.7152, 0.0722));\n}\n\nvec3 spectrum(float phase) {\n  vec3 display = 0.5 + 0.5 * cos(TAU * (phase + vec3(0.0, 0.33, 0.67)));\n  return display * display;\n}\n\nfloat aastep(float edge, float value) {\n  float width = max(fwidth(value), 1e-5) * 0.75;\n  return smoothstep(edge - width, edge + width, value);\n}\n\n// Coverage of |offset| < halfWidth with a one-pixel soft edge.\nfloat aaband(float offset, float halfWidth) {\n  float width = max(fwidth(offset), 1e-5);\n  return 1.0 - smoothstep(halfWidth - width, halfWidth + width, abs(offset));\n}\n\nint bayerIndex(ivec2 cell) {\n  int x = cell.x & 7;\n  int y = cell.y & 7;\n  int z = x ^ y;\n  return ((z & 1) << 5) | ((y & 1) << 4) | ((z & 2) << 2) | ((y & 2) << 1) | ((z & 4) >> 1) | ((y & 4) >> 2);\n}\n\nfloat bayer8(vec2 cell) {\n  return (float(bayerIndex(ivec2(floor(cell)))) + 0.5) / 64.0;\n}\n\nvec3 linearToSrgb(vec3 color) {\n  color = max(color, vec3(0.0));\n  return mix(color * 12.92, 1.055 * pow(color, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), color));\n}\n\n// Untouched below 0.82; brighter values roll off toward white instead of clipping.\nvec3 highlightShoulder(vec3 color) {\n  float peak = max(max(color.r, color.g), color.b);\n  if (peak <= 0.82) return color;\n  float mapped = 0.82 + 0.18 * (1.0 - exp(-(peak - 0.82) / 0.18));\n  return mix(color * (mapped / peak), vec3(mapped), clamp((peak - 1.0) * 0.3, 0.0, 0.55));\n}\n\nvoid writeColorWithGrain(vec3 color, float grainAmount) {\n  // Brightness keeps its display-space meaning from earlier versions.\n  color = highlightShoulder(max(color, vec3(0.0)) * pow(max(u_brightness, 0.0), 2.2));\n  vec3 display = linearToSrgb(color);\n  float grainCell = max(1.0, u_resolution.y / 1100.0);\n  vec2 grainCoord = floor(FC.xy / grainCell);\n  float frame = mod(floor(u_time * 24.0), 61.0);\n  float grain = hash12(grainCoord + frame * vec2(17.0, 59.0)) + hash12(grainCoord.yx + frame * vec2(41.0, 23.0)) - 1.0;\n  float tone = luma(display);\n  display += grain * (grainAmount / 100.0) * 0.2 * (0.55 + 1.8 * tone * (1.0 - tone));\n  // Triangular one-step dither removes 8-bit banding from smooth gradients.\n  \n  outColor = vec4(clamp(display, 0.0, 1.0), 1.0);\n}\n\nvoid writeColor(vec3 color) {\n  writeColorWithGrain(color, u_grain);\n}\n\nvoid groundMain() {\n  float cellSize = mix(2.0, 9.0, clamp(u_grain / 100.0, 0.0, 1.0));\n  vec2 cell = floor(referenceCoord() / cellSize);\n  vec2 p = studioUvAt(referenceToFrag((cell + 0.5) * cellSize));\n  float time = u_time * 0.3;\n  vec2 q = warp(p * max(0.45, u_detail * 0.2), time, 0.4 + u_strength * 1.1, 3);\n  float flow = 0.5 + 0.5 * sin((q.x + q.y * 0.38) * (0.6 + u_frequency * 0.22) + time);\n  flow = mix(flow, fbm(vec3(q * 1.2, time * 0.5), 4) * 1.8 + 0.5, 0.4);\n  float level = clamp(smoothstep(0.18, 0.95, flow), 0.0, 0.999) * 2.0 * (1.0 - uSeat * (1.0 - smoothstep(0.8, 1.05, length((FC.xy / u_resolution - vec2(0.5, 0.6)) / vec2(0.42, 0.32)))));\n  float index = floor(level) + step(bayer8(cell), fract(level));\n  vec3 color = index < 0.5 ? u_color_a : index < 1.5 ? u_color_b : u_color_c;\n  writeColorWithGrain(color, 0.0);\n}\n","textures":{}},"jarhead":{"body":"float b2(vec2 a){a=floor(a);return fract(dot(a,vec2(.5,a.y*.75)));} float b4(vec2 a){return b2(.5*a)*.25+b2(a);} float bayer8(vec2 a){return b4(.5*a)*.25+b2(a);} uniform vec2 uRes; uniform float uCell,uPeak,uFloor,uBands; uniform vec3 uGround,uTone; uniform vec4 uL0,uL1; uniform vec2 uS; /* uS = strengths (1.0, 0.55) */ void groundMain(){ vec2 c=floor(FC.xy/uCell); vec2 q=(c+.5)*uCell/uRes; q.y=1.-q.y; float u=uFloor; u=max(u,uS.x*(uFloor+(1.-uFloor)*(1.-smoothstep(0.,1.,length((q-uL0.xy)/uL0.zw))))); u=max(u,uS.y*(uFloor+(1.-uFloor)*(1.-smoothstep(0.,1.,length((q-uL1.xy)/uL1.zw))))); float i=min(uBands,floor(u*uBands+bayer8(c))); outColor=vec4(mix(uGround,uTone,uPeak*i/uBands),1.); }\n","textures":{}},"katagami":{"body":"// Shared header every ground uses (WebGL2, GLSL ES 3.00).\n// resolution: drawing-buffer px; time: seconds; pointer: 0..1 (0.5,0.5 at rest); seed: per card.\n\nuniform vec2 resolution;\nuniform float time;\nuniform vec2 pointer;\nuniform float seed;\n\nfloat hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * vec3(.1031,.1030,.0973)); p3 += dot(p3, p3.yzx+33.33); return fract((p3.xx+p3.yz)*p3.zy); }\nfloat vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);\n  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }\n// Kevin's 4x4 ordered-Bayer matrix (the hero dissolve, src/components/name-conveyor-hero.tsx; Turboslide's screen)\nfloat bayer4(vec2 p){ ivec2 q = ivec2(mod(p,4.)); int i=q.x+q.y*4;\n  int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5); return (float(m[i])+.5)/16.; }\n// 8x8 Bayer (Jarhead's island, Prototemplate Dither Field 'bayer8')\nfloat bayer8(vec2 p){ ivec2 q = ivec2(mod(p,8.)); int i=q.x+q.y*8;\n  int m[64]=int[64](0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21);\n  return (float(m[i])+.5)/64.; }\n\n// Katagami ground: the specimen's construction sheet. The 128-unit design grid,\n// the five vertical metrics (1490 ascender/cap, 1118 x-height, 0 baseline,\n// -418 descender) as score-blue hairlines, and Bezier points drifting on the grid\n// as score squares with cut-red handles. Weight breathes 100..900 the way the\n// variable axis does. Material: katagami.kevinliu.studio hero; tokens from the\n// site's own sheet (--sheet #0e0f10, --rule #26282b, --score #6c94ff, --cut #ff5246).\nuniform vec3 inkSheet;   // #0e0f10\nuniform vec3 inkRule;    // #26282b\nuniform vec3 inkScore;   // #6c94ff\nuniform vec3 inkCut;     // #ff5246\nuniform float unitPx;    // px per font unit: 0.18\nuniform float uRail, uPeak;\nvoid groundMain(){\n  vec2 f = FC.xy;\n  float u = 1./unitPx;                         // px -> units\n  vec2 pu = f*u;\n  vec3 col = inkSheet;\n  // 128-unit grid\n  vec2 gm = abs(fract(pu/128.)-.5)*128.;\n  float grid = smoothstep(1.2*u, 0., min(gm.x, gm.y));\n  col = mix(col, inkRule, grid*.9);\n  // vertical metrics, baseline at 30% height\n  float base = resolution.y*.3*u;\n  float m = 1e9;\n  for(int i=0;i<4;i++){ float v = (i==0)?1490.:(i==1)?1118.:(i==2)?0.:-418.; m = min(m, abs(pu.y-(base+v))); }\n  col = mix(col, inkScore*.75, smoothstep(1.4*u, 0., m)*.8);\n  // drifting points: one per grid cell where hash allows, snapping between grid nodes\n  vec2 cellId = floor(pu/128.);\n  float h = hash12(cellId+seed);\n  if(h>.86){\n    float w = .5+.5*sin(time*.6 + h*6.283);   // the weight axis breathing\n    vec2 node = (cellId + .5 + (hash22(cellId)-.5)*.6*w)*128.;\n    vec2 d = abs(pu-node);\n    float rail = 1. - uRail * step(node.y, resolution.y * u * .2); float sq = step(max(d.x,d.y), 6.*u) * rail;\n    vec2 hnd = node + vec2(cos(h*40.), sin(h*40.))*44.*(.5+w);\n    // handle line node -> hnd\n    vec2 pa = pu-node, ba = hnd-node; float tt = clamp(dot(pa,ba)/dot(ba,ba),0.,1.);\n    float line = smoothstep(1.6*u, 0., length(pa-ba*tt));\n    float ring = smoothstep(1.6*u, 0., abs(length(pu-hnd)-5.*u));\n    col = mix(col, inkCut, max(line*.85, ring) * rail);\n    col = mix(col, inkScore, sq);\n  }\n  vec2 pk = (f / resolution - vec2(.5, .58)) * vec2(1., resolution.y / resolution.x); col += uPeak * vec3(.05, .07, .1) * exp(-dot(pk, pk) / .14);\n  outColor = vec4(col, 1.);\n}\n","textures":{}},"claude-of-tanks":{"body":"// Shared header every ground uses (WebGL2, GLSL ES 3.00).\n// resolution: drawing-buffer px; time: seconds; pointer: 0..1 (0.5,0.5 at rest); seed: per card.\n\nuniform vec2 resolution;\nuniform float time;\nuniform vec2 pointer;\nuniform float seed;\n\nfloat hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * vec3(.1031,.1030,.0973)); p3 += dot(p3, p3.yzx+33.33); return fract((p3.xx+p3.yz)*p3.zy); }\nfloat vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);\n  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }\n// Kevin's 4x4 ordered-Bayer matrix (the hero dissolve, src/components/name-conveyor-hero.tsx; Turboslide's screen)\nfloat bayer4(vec2 p){ ivec2 q = ivec2(mod(p,4.)); int i=q.x+q.y*4;\n  int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5); return (float(m[i])+.5)/16.; }\n// 8x8 Bayer (Jarhead's island, Prototemplate Dither Field 'bayer8')\nfloat bayer8(vec2 p){ ivec2 q = ivec2(mod(p,8.)); int i=q.x+q.y*8;\n  int m[64]=int[64](0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21);\n  return (float(m[i])+.5)/64.; }\n\n// Claude of Tanks ground: the desert map's wind-rippled sand under the Studio sky,\n// printed in two inks through Kevin's 4x4 ordered-Bayer screen, crossed by one\n// APFSDS tracer on the shell's real flat trajectory. Material: cot.kevinliu.studio\n// desert map (Scene Studio), effect language 'tracer'. Pointer turns the wind.\nuniform vec3 inkSand;    // #f0b786\nuniform vec3 inkShadow;  // #957349\nuniform vec3 inkSky;     // #568bc0\nuniform vec3 inkTracer;  // #ffd27a (studio marker amber, src/game/studio.js:167)\nuniform float cell;      // Bayer cell in px (device): 3.0\nuniform float ripple;    // ripples per screen height: 38.0\nuniform float horizon;   // 0..1 from bottom: 0.62\nvoid groundMain(){\n  vec2 uv = FC.xy / resolution; float ar = resolution.x/resolution.y;\n  vec2 p = vec2(uv.x*ar, uv.y);\n  float wind = (pointer.x-.5)*.6;\n  // sand: ripples bent by low-frequency dunes, darker in troughs\n  float dune = vnoise(p*vec2(2.2,3.5)+seed) * .9 + vnoise(p*6.+seed*2.)*.25;\n  float r = sin((p.y*ripple + dune*7. + p.x*(.9+wind)*6.) ) * .5 + .5;\n  float shade = clamp(.25 + .55*r*smoothstep(horizon, 0., uv.y) + .2*dune, 0., 1.);\n  float d = bayer4(floor(FC.xy / cell));\n  vec3 sand = mix(inkShadow, inkSand, step(d, shade));\n  // sky above the horizon: the same screen, sky ink against pale haze\n  float sky = smoothstep(horizon-.01, horizon+.01, uv.y);\n  float haze = clamp(1.2 - (uv.y-horizon)*2.6, 0., 1.);\n  vec3 skyc = mix(inkSky, mix(inkSky, inkSand, .55), step(d, haze*.8));\n  vec3 col = mix(sand, skyc, sky);\n  // the tracer: a hot streak that crosses every 2.4 s\n  float t = fract(time/2.4 + seed);\n  vec2 a = vec2(-.2*ar, horizon+.06), b = vec2(1.2*ar, horizon+.16);\n  vec2 head = mix(a, b, t);\n  vec2 dir = normalize(b-a); vec2 q = p - head;\n  float along = dot(q, dir), across = abs(dot(q, vec2(-dir.y, dir.x)));\n  float streak = smoothstep(.004, 0., across) * smoothstep(-.55, 0., along) * step(along, 0.);\n  col = mix(col, inkTracer, streak * smoothstep(0.,.08,t) * smoothstep(1.,.85,t));\n  outColor = vec4(col, 1.);\n}\n","textures":{}},"mailroom":{"body":"uniform vec2 uRes; uniform float uGrid,uR0,uR1,uAlpha,uT; uniform vec3 uPage,uInk; uniform vec2 uC; void groundMain(){ vec2 p=FC.xy; p.y=uRes.y-p.y; vec2 g=mod(p-vec2(uT/4.*uGrid,0.),uGrid)-uGrid*.5; float dt=clamp((uR1-length(g))/(uR1-uR0),0.,1.); vec2 e=(p/uRes-uC)/.72; float m=clamp(1.-(length(e*.4)-.3)/(.72-.3),0.,1.); outColor=vec4(mix(uPage,uInk,dt*uAlpha*m),1.); }\n","textures":{}},"local-search":{"body":"/* atlas: one row of Katagami Mono glyphs for the stream's charset; uStream: the stream as glyph indices in an R8 texture */ uniform sampler2D uAtlas,uStream; uniform vec2 uRes,uCell; uniform float uN,uGlyphs,uShift; uniform vec3 uPage,uInk,uAcc; uniform float uRail; void groundMain(){ vec2 p=FC.xy; p.y=uRes.y-p.y; vec2 c=floor(p/uCell); float i=mod(c.x+c.y*37.+uShift,uN); vec2 s=texture(uStream,vec2((i+.5)/uN,.5)).rg; vec2 a=(vec2(s.r*255.,0.)+fract(p/uCell))/vec2(uGlyphs,1.); float g=texture(uAtlas,a).r; vec2 q=p/uRes; float fade=pow(clamp(1.15-length((q-.5)/1.4),0.,1.),1.2)*(1.-uRail*smoothstep(.76,.86,q.y)); vec3 col=s.g>.5?uAcc:uInk; float al=g*fade*(s.g>.5?1.:.62); outColor=vec4(mix(uPage,col,al),1.); }\n","textures":{"uAtlas":"glyph-atlas","uStream":"glyph-stream"}},"agent-pets":{"body":"// Shared header every ground uses (WebGL2, GLSL ES 3.00).\n// resolution: drawing-buffer px; time: seconds; pointer: 0..1 (0.5,0.5 at rest); seed: per card.\n\nuniform vec2 resolution;\nuniform float time;\nuniform vec2 pointer;\nuniform float seed;\n\nfloat hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * vec3(.1031,.1030,.0973)); p3 += dot(p3, p3.yzx+33.33); return fract((p3.xx+p3.yz)*p3.zy); }\nfloat vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);\n  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }\n// Kevin's 4x4 ordered-Bayer matrix (the hero dissolve, src/components/name-conveyor-hero.tsx; Turboslide's screen)\nfloat bayer4(vec2 p){ ivec2 q = ivec2(mod(p,4.)); int i=q.x+q.y*4;\n  int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5); return (float(m[i])+.5)/16.; }\n// 8x8 Bayer (Jarhead's island, Prototemplate Dither Field 'bayer8')\nfloat bayer8(vec2 p){ ivec2 q = ivec2(mod(p,8.)); int i=q.x+q.y*8;\n  int m[64]=int[64](0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21);\n  return (float(m[i])+.5)/64.; }\n\n// Agent Pets ground: Cute Cat's Sunbeam garden from site/world-scenes.mjs ('garden'\n// palette mixed with pet-worlds.mjs cute-cat sky #f6e5dc at the site's own 90/82%),\n// rebuilt as three depth planes on a hard pixel grid (the hi-bit 2x atlas grid):\n// sky gradient quantized through 8x8 Bayer, a far hill, the picket fence band and\n// the earth floor. The pointer shifts the planes for parallax (the gaze feature).\nuniform vec3 inkSky;     // #9fc4bc\nuniform vec3 inkHorizon; // #eae2bd\nuniform vec3 inkFar;     // #93af80\nuniform vec3 inkMid;     // #668663\nuniform vec3 inkTrim;    // #d5d29b\nuniform vec3 inkGround;  // #8da66b\nuniform vec3 inkLight;   // #fff2b8\nuniform float pixel;     // art pixel in device px: 8.0\nvoid groundMain(){\n  vec2 f = floor(FC.xy/pixel)*pixel;   // hard pixel grid\n  vec2 uv = f/resolution;\n  vec2 par = (pointer-.5)*vec2(.04,.02);\n  float d = bayer8(FC.xy/pixel);\n  vec3 col = mix(inkHorizon, inkSky, step(d, smoothstep(.35,1.,uv.y)));\n  // sun\n  vec2 sun = vec2(.74,.82)+par*.3; float r = length((uv-sun)*vec2(resolution.x/resolution.y,1.));\n  col = mix(col, inkLight, step(r,.075));\n  // drifting pixel cloud bands\n  float cy = .7 + .05*sin(seed);\n  float cx = fract(uv.x*.6 - time*.01 + seed);\n  float cloud = step(abs(uv.y-cy), .02) * step(abs(cx-.3), .07) + step(abs(uv.y-cy-.035), .016)*step(abs(cx-.31),.04) + step(abs(uv.y-cy+.03), .012)*step(abs(cx-.29),.1);\n  col = mix(col, mix(inkLight, inkHorizon, .4), clamp(cloud,0.,1.)*.9);\n  // far hill and mid hill (garden scene curves), parallax by depth\n  float x = uv.x + par.x;\n  float far = .42 + .08*sin(x*3.1+1.2+seed) + .03*sin(x*7.+seed);\n  col = mix(col, inkFar, step(uv.y, far));\n  float x2 = uv.x + par.x*2.;\n  float mid = .30 + .05*sin(x2*2.3+.4+seed);\n  col = mix(col, inkMid, step(uv.y, mid));\n  // picket fence band\n  float fx = fract((uv.x+par.x*2.5)*14.);\n  float post = step(fx,.32) * step(uv.y, .36) * step(.22, uv.y);\n  float rail = (step(abs(uv.y-.33),.008)+step(abs(uv.y-.26),.008)) * step(.22,uv.y);\n  col = mix(col, inkTrim, clamp(post+rail,0.,1.));\n  // earth floor with dashes\n  float fl = step(uv.y, .2);\n  vec2 cellf = floor(FC.xy/(pixel*vec2(6.,3.)));\n  float dash = step(.86, hash12(cellf+seed)) * fl;\n  col = mix(col, inkGround, fl);\n  col = mix(col, inkMid, dash*.6);\n  outColor = vec4(col, 1.);\n}\n","textures":{}},"loop":{"body":"uniform float uTime,uGlow,uGrainPx; uniform vec3 uBase; uniform vec2 uRes,uC; float hash(vec2 p){vec3 p3=fract(vec3(p.xyx)*.1031);p3+=dot(p3,p3.yzx+33.33);return fract((p3.x+p3.y)*p3.z);} void groundMain(){ vec2 uv=vUv; float t=uTime*.15; vec3 base=uBase; float glow=smoothstep(.85,0.,length((uv-uC)*vec2(1.1,1.4))); vec3 acc=vec3(.91,.396,.039)*glow*uGlow; acc*=1.+(sin(uv.x*3.+t*.8)*.003+cos(uv.y*2.5-t*.6)*.003)*8.; float g=hash(floor(uv*uRes/uGrainPx)+floor(uTime*0.)*1000.)*.12; outColor=vec4(base+acc+vec3(g),1.); }\n","textures":{}},"agent-machines":{"body":"uniform vec2 uRes,uCore; uniform vec3 uPaper,uLine; uniform float uFade; uniform float uUnit,uDpr,uT; void groundMain(){ vec2 p=FC.xy/uDpr; p.y=uRes.y/uDpr-p.y; float r=length(p-uCore)/uUnit; float st=12.5,r0=208.75; float k=(r-r0)/st-uT/.8; float f=abs(k-floor(k+.5))*st*uUnit; float line=clamp(1.-f/1.1,0.,1.)*step(0.,r-r0); float fade=pow(clamp(1.-(r-r0)/uFade,0.,1.),1.6); vec3 c=mix(uPaper,uLine,line*fade*.5); outColor=vec4(c,1.); }\n","textures":{}},"prototemplate":{"body":"uniform vec2 uResolution;\nuniform float uTime;\nuniform vec3 uColorA;\nuniform vec3 uColorB;\nuniform vec3 uColorC;\nuniform float uStrength;\nuniform float uDetail;\nuniform float uFrequency;\nuniform float uGrain; uniform float uPx;\nuniform float uAmplitude;\nuniform float uDensity;\nuniform float uBrightness;\nuniform float uRotation;\n\nfloat hash(vec2 p) {\n  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);\n}\n\nfloat noise(vec2 p) {\n  vec2 i = floor(p);\n  vec2 f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0)), f.x), f.y);\n}\n\nfloat fbm(vec2 p) {\n  float value = 0.0;\n  float amplitude = 0.52;\n  for (int index = 0; index < 5; index++) {\n    value += amplitude * noise(p);\n    p = mat2(1.62, 1.18, -1.18, 1.62) * p + 0.17;\n    amplitude *= 0.5;\n  }\n  return value;\n}\n\nvec2 rot2(vec2 v, float a) {\n  return mat2(cos(a), -sin(a), sin(a), cos(a)) * v;\n}\n\nvec2 studioUv() {\n  vec2 uv = FC.xy / max(uResolution.xy, vec2(1.0));\n  vec2 p = uv * 2.0 - 1.0;\n  p.x *= uResolution.x / uResolution.y;\n  return rot2(p, radians(uRotation));\n}\n\nvec3 colorRamp(float t) {\n  return t < 0.5 ? mix(uColorA, uColorB, t * 2.0) : mix(uColorB, uColorC, (t - 0.5) * 2.0);\n}\n\nvec3 inks(float level) {\n  return level < 0.25 ? uColorA : level < 0.75 ? uColorB : uColorC;\n}\n\nfloat toneField(vec2 p, float time) {\n  float pigment = fbm(p * max(0.72, uDetail * 0.38) + vec2(time, -time * 0.72));\n  pigment += sin((p.x * 0.7 + p.y) * uFrequency + time) * 0.13 * uStrength;\n  return smoothstep(0.08, 0.92, pigment);\n}\n\nvec3 finishColor(vec3 color) {\n  float sparkle = (hash(FC.xy + uTime * 23.0) - 0.5) * (uGrain / 100.0) * 0.26;\n  return max(vec3(0.0), color * uBrightness + sparkle);\n}\n\nfloat bayer2(vec2 position) {\n  vec2 cell = mod(floor(position), 2.0);\n  return fract(cell.x * 0.5 + cell.y * 0.75);\n}\n\nfloat bayer8(vec2 position) {\n  return bayer2(position * 0.25) * 0.0625 + bayer2(position * 0.5) * 0.25 + bayer2(position);\n}\n\nvoid groundMain() {\n  vec2 p = studioUv();\n  float time = uTime * 0.36;\n  float flow = 0.5 + 0.5 * sin((p.x + p.y * 0.38 + fbm(p * max(0.8, uDetail) + time) * uStrength) * uFrequency);\n  float cellSize = mix(1.0, 4.0, uGrain / 100.0) * uPx;\n  float threshold = bayer8(FC.xy / cellSize);\n  float level = floor(clamp(flow + 0.5 - threshold, 0.0, 1.0) * 2.0) / 2.0;\n  outColor = vec4(max(vec3(0.0), inks(level) * uBrightness), 1.0);\n}\n","textures":{}},"bday-land":{"body":"// Shared header every ground uses (WebGL2, GLSL ES 3.00).\n// resolution: drawing-buffer px; time: seconds; pointer: 0..1 (0.5,0.5 at rest); seed: per card.\n\nuniform vec2 resolution;\nuniform float time;\nuniform vec2 pointer;\nuniform float seed;\n\nfloat hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * vec3(.1031,.1030,.0973)); p3 += dot(p3, p3.yzx+33.33); return fract((p3.xx+p3.yz)*p3.zy); }\nfloat vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);\n  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }\n// Kevin's 4x4 ordered-Bayer matrix (the hero dissolve, src/components/name-conveyor-hero.tsx; Turboslide's screen)\nfloat bayer4(vec2 p){ ivec2 q = ivec2(mod(p,4.)); int i=q.x+q.y*4;\n  int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5); return (float(m[i])+.5)/16.; }\n// 8x8 Bayer (Jarhead's island, Prototemplate Dither Field 'bayer8')\nfloat bayer8(vec2 p){ ivec2 q = ivec2(mod(p,8.)); int i=q.x+q.y*8;\n  int m[64]=int[64](0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21);\n  return (float(m[i])+.5)/64.; }\n\n// bday.land ground: butter paper with falling sticker confetti, the island's own\n// confetti in the palette's own inks (src/lib/palette.ts via brand/colors), each\n// piece with a white die-cut rim and a hard 4 px Marker Ink offset shadow, never a\n// gradient or blur (Birthdayland brand rules 1-5). Material: demo.bday.land.\nuniform vec3 inkPaper;   // #FFF3D6\nuniform vec3 inkInk;     // #2B1D14\nuniform vec3 c0;         // #FF5DA2 bubblegum\nuniform vec3 c1;         // #FF8A3D tangerine\nuniform vec3 c2;         // #FFE14D lemon\nuniform vec3 c3;         // #5CC8FF sky\nuniform vec3 c4;         // #B8E986 lime\nuniform vec3 c5;         // #7B5CFF grape\nuniform float size;      // confetti cell in px: 120.0\nuniform float fall; uniform float thin; uniform float uRail;      // fall speed, cells per second: 0.35\nfloat piece(vec2 q, float a, vec2 hw){ float c=cos(a), s=sin(a); q = mat2(c,-s,s,c)*q; vec2 d = abs(q)-hw; return max(d.x,d.y); }\nvoid groundMain(){\n  vec2 f = FC.xy;\n  vec3 col = inkPaper;\n  for(int layer=0; layer<2; layer++){\n    float sz = size*(layer==0?1.:.62);\n    vec2 g = vec2(f.x, f.y + time*fall*sz*(layer==0?1.:.7))/sz;\n    vec2 id = floor(g), lp = fract(g)-.5;\n    float h = hash12(id+seed+float(layer)*13.);\n    if(h < thin) continue;\n    vec2 off = (hash22(id+seed)-.5)*.5; vec2 q = (lp-off)*sz*(44./size);\n    float a = h*6.283 + time*(h-.5)*1.4;\n    vec2 hw = vec2(mix(5.,9.,h), mix(9.,15.,fract(h*7.))); if (uRail > 0.) { float cy = (id.y + .5 + off.y) * sz - time*fall*sz*(layer==0?1.:.7); hw *= clamp((cy - resolution.y * .13) / (resolution.y * .08), 0., 1.); if (hw.x < .75) continue; }\n    int k = int(floor(fract(h*13.)*6.));\n    vec3 ink = k==0?c0:k==1?c1:k==2?c2:k==3?c3:k==4?c4:c5;\n    float sh = piece(q-vec2(4.,-4.), a, hw);      // hard offset shadow\n    col = mix(col, inkInk, step(sh, 1.5));\n    float rim = piece(q, a, hw);\n    col = mix(col, vec3(1.), step(rim, 2.5));     // die-cut rim\n    col = mix(col, ink, step(rim, 0.));\n  }\n  outColor = vec4(col, 1.);\n}\n","textures":{}},"powerlifting":{"body":"// Princeton Powerlifting ground: the club's Stripes mark, nine blades on a 600 x 400 tile, from\n// Princeton-Powerlifting lib/brand/marks.ts stripes(), fitted to the card's width (blades enter from both edges,\n// as the mark is drawn) and repeated down the card, drifting slowly along y so the motion never shows a seam.\n// Uniforms and defaults: u_field #0B0B0C (Iron), u_blade #F58025 (Tiger), u_mix 0.2 (blade strength),\n// u_speed 8.0 css px per second (0 for a still), u_dpr devicePixelRatio. Draw at the card's own size.\n\nuniform vec2 u_resolution;\nuniform float u_time;\nuniform float u_dpr;\nuniform vec3 u_field;\nuniform vec3 u_blade;\nuniform float u_mix;\nuniform float u_speed;\n\n// [edge x, y top, y bottom, tip x, tip y, kink x, kink y]\nconst float BL[63] = float[63](0., 10., 44., 250., 40., 120., 30., 0., 92., 120., 330., 132., 170., 112., 0., 176., 214., 210., 214., 100., 200.,\n  0., 262., 292., 360., 300., 190., 284., 0., 340., 378., 240., 392., 120., 366., 600., 46., 80., 340., 74., 470., 62.,\n  600., 130., 168., 260., 172., 430., 152., 600., 220., 250., 380., 248., 500., 236., 600., 300., 340., 280., 336., 450., 322.);\nbool inPoly(vec2 p, vec2 a, vec2 b, vec2 c, vec2 d, vec2 e) {\n  vec2 v[5] = vec2[5](a, b, c, d, e);\n  bool inside = false;\n  for (int i = 0, j = 4; i < 5; j = i++) {\n    if (((v[i].y > p.y) != (v[j].y > p.y)) && (p.x < (v[j].x - v[i].x) * (p.y - v[i].y) / (v[j].y - v[i].y) + v[i].x)) inside = !inside;\n  }\n  return inside;\n}\nvoid groundMain() {\n  vec2 css = vec2(FC.x, u_resolution.y - FC.y) / u_dpr;\n  float s = 600.0 / max(1.0, u_resolution.x / u_dpr);\n  vec2 p = vec2(css.x * s, mod((css.y + u_time * u_speed) * s, 400.0));\n  bool hit = false;\n  for (int i = 0; i < 9; i++) {\n    float ex = BL[i * 7], y1 = BL[i * 7 + 1], y2 = BL[i * 7 + 2], tx = BL[i * 7 + 3], ty = BL[i * 7 + 4], kx = BL[i * 7 + 5], ky = BL[i * 7 + 6];\n    float k = (y2 - y1) * 0.35;\n    if (inPoly(p, vec2(ex, y1), vec2(kx, ky - k), vec2(tx, ty), vec2(kx, ky + k), vec2(ex, y2))) hit = true;\n  }\n  outColor = vec4(hit ? mix(u_field, u_blade, u_mix) : u_field, 1.0);\n}\n","textures":{}},"elo":{"body":"// Elo halo ground: the winner's spotlight from Kevin-Liu-01/Elo src/ui/halftone.ts, as a fragment shader.\n// TONES.halo = 0.95 * clamp(1 - hypot((x - .5) / r, (y - .5) / r), 0, 1)^1.5 over the box (r 0.47 in the app),\n// printed on the 8 x 8 Bayer screen at PITCH 3 css px with 2 css px dots, one ink on paper.\n// Uniforms and defaults: u_ink #5B82FF on u_paper #070707 (dark) or #2F5CE0 on #FFFFFF (light); u_radius 0.47;\n// u_breath 0.0 (set 0.02 for a slow swell, u_period 6.0 s); u_center 0.5, 0.5 (move it to follow the pointer).\n\nuniform vec2 u_resolution;\nuniform float u_time;\nuniform float u_dpr;\nuniform vec3 u_ink;\nuniform vec3 u_paper;\nuniform float u_radius;\nuniform float u_breath;\nuniform float u_period;\nuniform vec2 u_center;\n\nfloat bayer8(vec2 c) {\n  // the 8 x 8 matrix halftone.ts builds by recursion from [[0, 2], [3, 1]]: the lowest bit pair is the most significant digit\n  ivec2 p = ivec2(mod(c, 8.0));\n  int v = 0;\n  for (int k = 0; k < 3; k++) {\n    int bx = (p.x >> k) & 1, by = (p.y >> k) & 1;\n    v = v * 4 + (by == 0 ? (bx == 0 ? 0 : 2) : (bx == 0 ? 3 : 1));\n  }\n  return (float(v) + 0.5) / 64.0;\n}\nvoid groundMain() {\n  vec2 css = vec2(FC.x, u_resolution.y - FC.y) / u_dpr;\n  vec2 box = u_resolution / u_dpr;\n  vec2 cell = floor(css / 3.0);\n  vec2 inCell = css - cell * 3.0;\n  vec2 cols = ceil(box / 3.0);\n  vec2 uv = (cell + 0.5) / cols;\n  float r = u_radius + u_breath * sin(6.28318530718 * u_time / max(u_period, 0.001));\n  float tone = 0.95 * pow(clamp(1.0 - length((uv - u_center) / r), 0.0, 1.0), 1.5);\n  bool dot = inCell.x < 2.0 && inCell.y < 2.0 && tone > bayer8(cell);\n  outColor = vec4(dot ? u_ink : u_paper, 1.0);\n}\n","textures":{}},"cotfly":{"body":"// Shared header every ground uses (WebGL2, GLSL ES 3.00).\n// resolution: drawing-buffer px; time: seconds; pointer: 0..1 (0.5,0.5 at rest); seed: per card.\n\nuniform vec2 resolution;\nuniform float time;\nuniform vec2 pointer;\nuniform float seed;\n\nfloat hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * vec3(.1031,.1030,.0973)); p3 += dot(p3, p3.yzx+33.33); return fract((p3.xx+p3.yz)*p3.zy); }\nfloat vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);\n  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }\n// Kevin's 4x4 ordered-Bayer matrix (the hero dissolve, src/components/name-conveyor-hero.tsx; Turboslide's screen)\nfloat bayer4(vec2 p){ ivec2 q = ivec2(mod(p,4.)); int i=q.x+q.y*4;\n  int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5); return (float(m[i])+.5)/16.; }\n// 8x8 Bayer (Jarhead's island, Prototemplate Dither Field 'bayer8')\nfloat bayer8(vec2 p){ ivec2 q = ivec2(mod(p,8.)); int i=q.x+q.y*8;\n  int m[64]=int[64](0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21);\n  return (float(m[i])+.5)/64.; }\n\n// CoTFly ground: the Neural Link pane. 124 somata scattered like the MaleCNS\n// cluster, each a leaky integrate-and-fire cell (tau 20 ms, rest -65 mV,\n// threshold -50 mV, refractory 3 ms, src/fly/connectome.ts) stepped from time;\n// a cell flashes amber when it spikes, and the population raster scrolls along\n// the bottom like the console's six-second history. Material: fly.kevinliu.studio.\nuniform vec3 inkStage;   // #101d18\nuniform vec3 inkSage;    // #c2cbad (the CoTFly mark)\nuniform vec3 inkSpike;   // #e4c887 (brass)\nuniform vec3 inkHot;     // #d23525 (compound eye red)\nuniform float drive;     // input current, 0..1 (Sugar Boost raises it): 0.55\nuniform float slow;      // time dilation so spikes read: 40.0\nfloat vAt(float t, float rate){ // membrane trace of a periodically driven LIF, -65..-50\n  float period = (.003 + 1./max(rate,.1)); float ph = fract(t/period);\n  return -65. + 15.*(1.-exp(-ph*period/.02))/(1.-exp(-period/.02)); }\nvoid groundMain(){\n  vec2 f = FC.xy; vec2 uv = f/resolution; float ar = resolution.x/resolution.y;\n  vec3 col = inkStage;\n  vec2 p = vec2(uv.x*ar, uv.y);\n  float t = time/slow;\n  // somata: a jittered lattice, culled to an hourglass so it reads as the cluster\n  float sc = 15.; vec2 gid = floor(p*sc); vec3 acc = vec3(0.);\n  for(int j=-1;j<=1;j++) for(int i=-1;i<=1;i++){\n    vec2 id = gid+vec2(i,j); vec2 c = (id + hash22(id+seed))/sc;\n    float hx = abs(c.x - ar*.5)/(ar*.5), hy = abs(c.y-.55)/.45;\n    if(hash12(id*1.7+seed) > .55 + .35*(1.-abs(hx-hy))) continue;\n    float rate = 10. + 60.*drive*hash12(id+3.1);\n    float v = vAt(t + hash12(id+9.)*.3, rate);\n    float spike = smoothstep(-50.6, -50., v);\n    float d = length(p-c);\n    acc += inkSage * smoothstep(.006, .0, d) * .55;\n    acc += mix(inkSpike, inkHot, hash12(id+5.)) * smoothstep(.022, .0, d) * spike;\n    // faint edge toward the cluster center, the measured mAL -> P1 direction\n    vec2 to = vec2(ar*.5, .55) - c; float along = clamp(dot(p-c, to)/dot(to,to), 0., 1.);\n    acc += inkSage * smoothstep(.0012, .0, length(p-c-to*along)) * .05 * (1.-along);\n  }\n  col += acc;\n  // population raster: 6 s history scrolling left\n  if(uv.y < .12){\n    float row = floor(uv.y/.12*24.); float colx = floor((uv.x*ar + t*.6)*120.);\n    float on = step(.93 - drive*.1, hash12(vec2(colx,row)+seed));\n    col = mix(col, inkSpike, on*.8);\n  }\n  outColor = vec4(col, 1.);\n}\n","textures":{}},"relay":{"body":"uniform sampler2D uM; /* 18 x 17 R8 texture: 1.0 passed, 0.5 incomplete, 0.0 blocked; NEAREST */ uniform vec2 uRes; uniform float uT; uniform vec3 uPlum,uPass,uInc,uBlk; void groundMain(){ vec2 q=FC.xy/uRes; q.y=1.-q.y; vec2 g=q*vec2(18.,17.); vec2 f=fract(g)-.5; float v=texture(uM,(floor(g)+.5)/vec2(18.,17.)).r; vec3 c=v>.75?uPass:(v>.25?uInc:uBlk); float ix=floor(g.y)*18.+floor(g.x); float lit=smoothstep(10.,0.,mod(mod(uT*18.,306.)-ix+306.,306.)); c=mix(c,min(c*1.45+.06,vec3(1.)),lit*(v>.75?1.:.55)); float rr=.1; float sd=length(max(abs(f)-(vec2(.4)-rr),0.))-rr; float a=1.-smoothstep(0.,fwidth(sd)*1.5,sd); float d=length((q-vec2(.5,.41))/vec2(1.,.8)); float k=clamp(1.-.55*clamp(d-.25,0.,1.),.45,1.); outColor=vec4(uPlum+(mix(uPlum,c,a)-uPlum)*k,1.); }\n","textures":{"uM":"relay-matrix"}},"princeton-td":{"body":"// Shared header every ground uses (WebGL2, GLSL ES 3.00).\n// resolution: drawing-buffer px; time: seconds; pointer: 0..1 (0.5,0.5 at rest); seed: per card.\n\nuniform vec2 resolution;\nuniform float time;\nuniform vec2 pointer;\nuniform float seed;\n\nfloat hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * vec3(.1031,.1030,.0973)); p3 += dot(p3, p3.yzx+33.33); return fract((p3.xx+p3.yz)*p3.zy); }\nfloat vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);\n  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }\n// Kevin's 4x4 ordered-Bayer matrix (the hero dissolve, src/components/name-conveyor-hero.tsx; Turboslide's screen)\nfloat bayer4(vec2 p){ ivec2 q = ivec2(mod(p,4.)); int i=q.x+q.y*4;\n  int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5); return (float(m[i])+.5)/16.; }\n// 8x8 Bayer (Jarhead's island, Prototemplate Dither Field 'bayer8')\nfloat bayer8(vec2 p){ ivec2 q = ivec2(mod(p,8.)); int i=q.x+q.y*8;\n  int m[64]=int[64](0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21);\n  return (float(m[i])+.5)/64.; }\n\n// Princeton TD ground: the campus map's isometric tile floor (2:1 diamonds, the\n// projection Prototemplate Iso Kit and the game's offscreen map layer share),\n// in the winter biome inks, with the wave path cut through it as data: tiles\n// on the path light up in the order a wave would walk them. Material: ptd.quest\n// isometric map, src/app/constants/waves.ts (groups, interval, delay).\nuniform vec3 inkGround;  // #2b3446 winter slate\nuniform vec3 inkTile;    // #3b4760\nuniform vec3 inkPath;    // #c9d3e6 packed snow road\nuniform vec3 inkGlow;    // #6fd3ff E-Quad Lab orb\nuniform float tile;      // tile width in px: 96.0\nuniform float interval;  // seconds between spawns (waves.ts frosh interval 850 ms): 0.85\nvoid groundMain(){\n  vec2 f = FC.xy;\n  // iso basis: screen -> tile coords (2:1)\n  vec2 iso = vec2(f.x/tile + f.y/(tile*.5), -f.x/tile + f.y/(tile*.5)) * .5;\n  vec2 id = floor(iso), g = fract(iso);\n  float edge = min(min(g.x,1.-g.x), min(g.y,1.-g.y));\n  float h = hash12(id + seed);\n  vec3 col = mix(inkGround, inkTile, .35 + .4*h);\n  col = mix(col, inkGround*.8, smoothstep(.06, .0, edge));       // grout\n  // the path: a meander in tile space (a wave route), drawn as a band of tiles\n  float route = id.y - 6.*sin(id.x*.32 + seed) - 2.*sin(id.x*.11);\n  float onPath = step(abs(route), 1.5);\n  col = mix(col, inkPath, onPath*.85);\n  // a wave walks the path: tiles flash as each enemy passes (interval-spaced)\n  float march = fract((id.x*.18 - time/interval*.18));\n  float pulse = onPath * smoothstep(.08, 0., abs(march-.5)) * (.6+.4*h);\n  col = mix(col, inkGlow, pulse*.7);\n  // towers: sparse glowing orbs beside the path\n  vec2 c = id + .5; float tower = step(.93, hash12(floor(id/3.)+seed*7.)) * step(abs(route), 3.5) * (1.-onPath);\n  float orb = smoothstep(.32, .0, length(g-.5)) * tower * (.65+.35*sin(time*6.+h*20.));\n  col += inkGlow * orb;\n  outColor = vec4(col, 1.);\n}\n","textures":{}},"kevin-wiki":{"body":"// Kevin Wiki ground: the wiki's own public link graph (ground-source.webp, a still of the live graph from this plate)\n// re-printed through the hero's 4x4 ordered Bayer screen at print cells, three levels from the reader's ground #11100E\n// to each cell's own category colour, turning a few degrees about the graph's centre the way the reader's orbit does.\n// Uniforms and defaults: u_graph = ground-source.webp; u_cell 3.0 css px; u_ground #11100E; u_gain 0.75;\n// u_turn 0.035 rad of sway; u_period 24.0 s (sway clock).\n\nuniform vec2 u_resolution;\nuniform float u_time;\nuniform float u_dpr;\nuniform sampler2D u_graph;\nuniform vec2 u_graph_size;\nuniform float u_cell;\nuniform vec3 u_ground;\nuniform float u_gain;\nuniform float u_turn;\nuniform float u_period;\n\nfloat bayer4(vec2 p) {\n  vec2 c = mod(floor(p), 4.0);\n  int i = int(c.y) * 4 + int(c.x);\n  int m[16] = int[16](0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5);\n  return (float(m[i]) + 0.5) / 16.0;\n}\nvoid groundMain() {\n  float cell = max(1.0, u_cell * u_dpr);\n  vec2 cellC = (floor(FC.xy / cell) + 0.5) * cell;\n  // cover-fit the graph still, then sway it about the centre\n  vec2 uv = (cellC / u_resolution - 0.5) * 0.5;\n  float ar = (u_resolution.x / u_resolution.y) / (u_graph_size.x / u_graph_size.y);\n  uv.x *= ar > 1.0 ? 1.0 : ar; uv.y /= ar > 1.0 ? ar : 1.0;\n  float a = u_turn * sin(6.28318530718 * u_time / max(u_period, 0.001));\n  uv = mat2(cos(a), -sin(a), sin(a), cos(a)) * uv;\n  vec3 src = texture(u_graph, vec2(uv.x + 0.5, 0.5 - uv.y)).rgb;\n  float lum = clamp((max(src.r, max(src.g, src.b)) - u_ground.r) * u_gain * 1.6, 0.0, 1.0);\n  float hue = max(max(src.r, src.g), max(src.b, 1e-3));\n  vec3 ink = src / hue;\n  float level = floor(clamp(lum * 2.0 + 0.5 - bayer4(FC.xy / cell), 0.0, 2.0)) / 2.0;\n  outColor = vec4(mix(u_ground, ink * 0.9, level * 0.85), 1.0);\n}\n","textures":{"u_graph":"data:image/webp;base64,"}}};
